-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(
    materialized='incremental',
    incremental_strategy=dpf_incremental_strategy({"bigquery": "merge", "duckdb": "delete+insert"}),
    unique_key=["legal_vehicle_hk", "effective_from", "hashdiff_basis_version"]
) }}

with
sat_legal_vehicle_detail_source as (
    select distinct
        vehicle_business_key,
        vehicle_name,
        vehicle_type,
        vehicle_jurisdiction,
        vehicle_incorporated_on,
        vehicle_lei,
        vehicle_fund_business_key,
        vehicle_fund_source_id,
        vehicle_parent_source_id,
        vehicle_reported_on
    from {{ ref("investment__legal_vehicle_vault__base") }}
    where vehicle_business_key is not null
),
sat_legal_vehicle_detail_fingerprinted as (
    select
        {{ dpf_vault_hash(["vehicle_business_key"]) }} as legal_vehicle_hk,
        {{ dpf_vault_hash(["vehicle_name", "vehicle_type", "vehicle_jurisdiction", "vehicle_incorporated_on", "vehicle_lei", "vehicle_fund_business_key"]) }} as hashdiff,
        1 as hashdiff_basis_version,
        vehicle_name,
        vehicle_type,
        vehicle_jurisdiction,
        vehicle_incorporated_on,
        vehicle_lei,
        vehicle_fund_business_key,
        vehicle_fund_source_id,
        vehicle_parent_source_id,
        vehicle_reported_on as effective_from,
        {{ dpf_publish_timestamp() }} as load_datetime,
        'investment.legal_vehicle_vault' as record_source
    from sat_legal_vehicle_detail_source
),
sat_legal_vehicle_detail_unstored as (
    select
        legal_vehicle_hk,
        hashdiff,
        hashdiff_basis_version,
        vehicle_name,
        vehicle_type,
        vehicle_jurisdiction,
        vehicle_incorporated_on,
        vehicle_lei,
        vehicle_fund_business_key,
        vehicle_fund_source_id,
        vehicle_parent_source_id,
        effective_from,
        load_datetime,
        record_source
    from sat_legal_vehicle_detail_fingerprinted
    where {{ dpf_vault_new_versions("sat_legal_vehicle_detail_fingerprinted", "legal_vehicle_hk", "hashdiff", "effective_from", "hashdiff_basis_version", "current") }}
)

select
    cast(legal_vehicle_hk as {{ dpf_type('string') }}) as legal_vehicle_hk,
    cast(hashdiff as {{ dpf_type('string') }}) as hashdiff,
    cast(hashdiff_basis_version as {{ dpf_type('int') }}) as hashdiff_basis_version,
    cast(vehicle_name as {{ dpf_type('string') }}) as vehicle_name,
    cast(vehicle_type as {{ dpf_type('string') }}) as vehicle_type,
    cast(vehicle_jurisdiction as {{ dpf_type('string') }}) as vehicle_jurisdiction,
    cast(vehicle_incorporated_on as {{ dpf_type('date') }}) as vehicle_incorporated_on,
    cast(vehicle_lei as {{ dpf_type('string') }}) as vehicle_lei,
    cast(vehicle_fund_business_key as {{ dpf_type('string') }}) as vehicle_fund_business_key,
    cast(vehicle_fund_source_id as {{ dpf_type('string') }}) as vehicle_fund_source_id,
    cast(vehicle_parent_source_id as {{ dpf_type('string') }}) as vehicle_parent_source_id,
    cast(effective_from as {{ dpf_type('date') }}) as effective_from,
    cast(load_datetime as {{ dpf_type('timestamp') }}) as load_datetime,
    cast(record_source as {{ dpf_type('string') }}) as record_source
from sat_legal_vehicle_detail_unstored
